-- Data: Academy AI Video Production follow-up automation (idempotent; revert by deleting the automation by name).
with a as (insert into automations (user_id,workspace_id,name,description,trigger_type,trigger_event,trigger_source,trigger_config,status,exit_criteria,enrollment_object_type,enrollment_method,filter_groups,reenrollment_config)
select 'afd12255-5ad7-46f9-8588-c51cf1ed1f72','95bc7e99-798e-49ef-a5c3-ab68bbc08950','Academy – AI Video Production: Class Booking & Follow-up','Starts when a student pays for AI Video Production for Small Businesses. Reminds them to book, sends prep 24h before class, then resources and trial offer the day after.','lead_tagged','lead_tagged','crm','{"tags": "ai-video-production-for-small-businesses"}'::jsonb,'active','[{"type": "unsubscribed"}]'::jsonb,'lead','automatic','[]'::jsonb,'{"mode": "never"}'::jsonb where not exists (select 1 from automations where workspace_id='95bc7e99-798e-49ef-a5c3-ab68bbc08950' and name='Academy – AI Video Production: Class Booking & Follow-up') returning id)
insert into automation_steps (automation_id,workspace_id,step_order,step_type,config) select a.id, '95bc7e99-798e-49ef-a5c3-ab68bbc08950'::uuid, x.o, x.t, x.c from a, (values (0,'delay','{"duration": 1, "unit": "days"}'::jsonb),(1,'condition','{"condition": "appointment_booked", "operator": "happened"}'::jsonb),(2,'branch_yes_start','{"label": "Already booked a class"}'::jsonb),(3,'branch_yes_end','{}'::jsonb),(4,'branch_no_start','{"label": "Not booked yet \u2014 reminder 1"}'::jsonb),(5,'action','{"action": "send_email", "subject": "Next step: choose your live class date for AI Video Production \ud83c\udfac", "body": "Hi {{first_name}},\n\nJust checking in! You enrolled in AI Video Production for Small Businesses, but you haven''t reserved your live class time yet.\n\nSlots are available on weekdays and fill up quickly. Choose a 60-minute time that suits you here:\n\n<a href=\"https://nexusflo24.com/book/academy-live-class?email={{email}}&name={{first_name}}\" style=\"color:#0B1F3B;text-decoration:underline\">Pick your live class date & time</a>\n\nIf you have any questions or need a different time, just reply to this email.\n\nBest regards,\nKizito Adichie\nFounder, NexusFlo24 Academy"}'::jsonb),(6,'branch_no_end','{}'::jsonb),(7,'delay','{"duration": 2, "unit": "days"}'::jsonb),(8,'condition','{"condition": "appointment_booked", "operator": "happened"}'::jsonb),(9,'branch_yes_start','{"label": "Booked"}'::jsonb),(10,'branch_yes_end','{}'::jsonb),(11,'branch_no_start','{"label": "Still not booked \u2014 reminder 2"}'::jsonb),(12,'action','{"action": "send_email", "subject": "Your live class slot is waiting \u2014 let''s get you producing AI videos", "body": "Hi {{first_name}},\n\nWe want to make sure you get the most out of your enrolment. Your live session is where we tailor the AI tools directly to your business.\n\n<a href=\"https://nexusflo24.com/book/academy-live-class?email={{email}}&name={{first_name}}\" style=\"color:#0B1F3B;text-decoration:underline\">Secure your live class slot</a>\n\nOnce you choose a time, you''ll receive your meeting link straight away.\n\nTalk soon,\nKizito Adichie"}'::jsonb),(13,'action','{"action": "notify_sales", "title": "Academy student hasn''t booked", "message": "{{first_name}} {{last_name}} paid for AI Video Production but hasn''t booked a live class after 3 days. Consider reaching out."}'::jsonb),(14,'branch_no_end','{}'::jsonb),(15,'delay','{"duration": 1, "unit": "days", "anchor": "booking_start", "offset_minutes": -1440, "booking_page_id": "4304162a-aba3-416a-83c5-467242f3c37d", "label": "Wait until 24 hours before the class"}'::jsonb),(16,'action','{"action": "send_email", "subject": "See you tomorrow! Prep checklist for your AI Video class \ud83d\ude80", "body": "Hi {{first_name}},\n\nLooking forward to our live session tomorrow! Your meeting link is in your booking confirmation email.\n\nTo make the most of our 60 minutes together, please prepare:\n\n1. Bring 2\u20133 video ideas you want to create for your business (e.g. a customer testimonial, product demo or social media ad).\n2. Check your microphone and camera so we can share screens and build live.\n\nSee you inside the session!\n\nBest,\nKizito"}'::jsonb),(17,'delay','{"duration": 1, "unit": "days", "anchor": "booking_end", "offset_minutes": 1440, "booking_page_id": "4304162a-aba3-416a-83c5-467242f3c37d", "label": "Wait until 1 day after the class"}'::jsonb),(18,'action','{"action": "send_email", "subject": "Your AI Video resources + next step for your marketing", "body": "Hi {{first_name}},\n\nFantastic session! You now have the skills to produce high-converting AI videos without expensive equipment or editing teams.\n\nNext step: producing the videos is step one \u2014 getting them in front of paying customers automatically is step two.\n\nAs an Academy student, you can start a 14-day free trial of NexusFlo24 to automate your video marketing, lead follow-up, WhatsApp campaigns and CRM:\n\n<a href=\"https://nexusflo24.com/register?email={{email}}\" style=\"color:#0B1F3B;text-decoration:underline\">Start your 14-day free trial</a>\n\nIf you enjoyed the class, I''d love your feedback or a quick testimonial \u2014 just reply to this email.\n\nWarm regards,\nKizito Adichie"}'::jsonb),(19,'action','{"action": "add_tag", "tag": "academy-class-completed"}'::jsonb)) as x(o,t,c);
